package com.example.proyectolp;

import com.example.proyectolp.model.DailyQuote;
import com.example.proyectolp.service.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.io.IOException;
import java.net.http.HttpTimeoutException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;

class MyMemoryQuoteTranslationTest {
    @TempDir Path temp;
    private static final ZoneId ZONE=ZoneId.of("America/Bogota");
    private static final Clock CLOCK=Clock.fixed(Instant.parse("2026-10-29T15:00:00Z"),ZONE);

    @Test void parsesResponseStatusAndDecodesEntities(){MyMemoryClient c=new MyMemoryClient((m,u,h,b)->new HttpTransport.Response(200,"{\"responseData\":{\"translatedText\":\"&quot;Hola&#39; &amp; mundo&quot;\"},\"responseStatus\":\"200\"}"));assertEquals("\"Hola' & mundo\"",assertDoesNotThrow(()->c.translate("Good morning")));MyMemoryClient numeric=new MyMemoryClient((m,u,h,b)->new HttpTransport.Response(200,"{\"responseData\":{\"translatedText\":\"Buenos días\"},\"responseStatus\":200}"));assertEquals("Buenos días",assertDoesNotThrow(()->numeric.translate("Good morning")));}
    @Test void quotaWarningNeverBecomesTranslation(){for(String status:List.of("200","403")){MyMemoryClient c=new MyMemoryClient((m,u,h,b)->new HttpTransport.Response(200,"{\"responseData\":{\"translatedText\":\"MYMEMORY WARNING: daily quota limit reached\"},\"responseStatus\":"+status+"}"));assertEquals(TranslationException.Kind.QUOTA,assertThrows(TranslationException.class,()->c.translate("Hello")).kind());}}
    @Test void non200ResponseStatusIsTreatedAsQuota(){MyMemoryClient client=new MyMemoryClient((m,u,h,b)->new HttpTransport.Response(200,"{\"responseData\":{\"translatedText\":\"\"},\"responseStatus\":403}"));assertEquals(TranslationException.Kind.QUOTA,assertThrows(TranslationException.class,()->client.translate("Hello")).kind());}
    @Test void refusesIdenticalTranslation(){MyMemoryClient c=client(200,"{\"responseData\":{\"translatedText\":\"Hello\"},\"responseStatus\":200}");assertEquals(TranslationException.Kind.OTHER,assertThrows(TranslationException.class,()->c.translate("Hello")).kind());}
    @Test void uriEncodesPairQueryAndOptionalEmail(){MyMemoryClient anon=new MyMemoryClient((m,u,h,b)->new HttpTransport.Response(200,"{}"));String uri=anon.buildUri("Hello there!").toASCIIString();assertTrue(uri.contains("langpair=en%7Ces"));assertTrue(uri.contains("q=Hello%20there%21"));assertFalse(uri.contains("+"));assertFalse(uri.contains("de="));MyMemoryClient contact=new MyMemoryClient((m,u,h,b)->new HttpTransport.Response(200,"{}"),"dev@example.com");assertTrue(contact.buildUri("Hi").toASCIIString().contains("de=dev%40example.com"));assertEquals(50000,contact.dailyCharacterLimit());assertEquals(5000,anon.dailyCharacterLimit());}
    @Test void partitionsByUtf8BytesAndKeepsOrder(){String text=("Ánimo “amiga”. ").repeat(80);List<String> chunks=MyMemoryClient.splitText(text,480);assertTrue(chunks.size()>1);for(String chunk:chunks)assertTrue(chunk.getBytes(StandardCharsets.UTF_8).length<=480);String longWord="é".repeat(300);assertTrue(MyMemoryClient.splitText(longWord,480).stream().allMatch(c->c.getBytes(StandardCharsets.UTF_8).length<=480));}
    @Test void sendsEveryChunkBelowTheByteLimit(){AtomicInteger requests=new AtomicInteger();MyMemoryClient client=new MyMemoryClient((m,u,h,b)->{requests.incrementAndGet();String raw=u.getRawQuery().split("&")[0].substring(2);String query=java.net.URLDecoder.decode(raw,StandardCharsets.UTF_8);assertTrue(query.getBytes(StandardCharsets.UTF_8).length<=480);return new HttpTransport.Response(200,"{\"responseData\":{\"translatedText\":\"Traducido\"},\"responseStatus\":200}");});assertDoesNotThrow(()->client.translate(("Una oracion con tilde. ").repeat(50)));assertTrue(requests.get()>1);}
    @Test void quoteFlowCachesTranslationAndDoesNotRepeatZenOrTranslation(){AtomicInteger zenCalls=new AtomicInteger(),translationCalls=new AtomicInteger();ZenQuotesClient zen=zenClient(zenCalls);QuoteTranslator translator=text->{translationCalls.incrementAndGet();return "Frase traducida";};QuoteService service=new QuoteService(zen,translator,new ZenQuotesCache(temp),CLOCK);var first=service.todayAsync(Runnable::run).join().orElseThrow();assertEquals("Frase traducida",first.displayText());assertEquals(1,zenCalls.get());assertEquals(1,translationCalls.get());var second=service.todayAsync(Runnable::run).join().orElseThrow();assertEquals(DailyQuote.Origin.CACHED,second.origin());assertEquals(1,zenCalls.get());assertEquals(1,translationCalls.get());}
    @Test void oldCacheOnlyTriggersTranslationAndFailureRetriesAfterCooldown()throws Exception{Path file=temp.resolve("zenquotes-cache.json");Files.writeString(file,"{\"text\":\"A quote\",\"author\":\"A\",\"date\":\"2026-10-29\",\"savedOn\":\"2026-10-29\"}");ZenQuotesCache cache=new ZenQuotesCache(temp);AtomicInteger zenCalls=new AtomicInteger(),translationCalls=new AtomicInteger();MutableClock clock=new MutableClock(CLOCK.instant(),ZONE);QuoteTranslator translator=text->{if(translationCalls.incrementAndGet()==1)throw new TranslationException(TranslationException.Kind.NETWORK,"offline");return "Una frase";};QuoteService service=new QuoteService(zenClient(zenCalls),translator,cache,clock);DailyQuote first=service.todayAsync(Runnable::run).join().orElseThrow();assertEquals(DailyQuote.TranslationStatus.ORIGINAL_ONLY,first.translationStatus());service.todayAsync(Runnable::run).join();assertEquals(0,zenCalls.get());clock.advance(Duration.ofMinutes(5));DailyQuote second=service.todayAsync(Runnable::run).join().orElseThrow();assertEquals("Una frase",second.displayText());assertEquals(0,zenCalls.get());assertEquals(2,translationCalls.get());}
    @Test void quotaMarkBlocksRestOfDayAndAllowsNextDay(){AtomicInteger zenCalls=new AtomicInteger(),translationCalls=new AtomicInteger();ZenQuotesClient zen=zenClient(zenCalls);QuoteTranslator translator=text->{if(translationCalls.incrementAndGet()==1)throw new TranslationException(TranslationException.Kind.QUOTA,"quota");return "Traducida";};ZenQuotesCache cache=new ZenQuotesCache(temp);MutableClock clock=new MutableClock(CLOCK.instant(),ZONE);QuoteService service=new QuoteService(zen,translator,cache,clock);DailyQuote q=service.todayAsync(Runnable::run).join().orElseThrow();assertEquals(DailyQuote.TranslationStatus.ORIGINAL_ONLY,q.translationStatus());service.todayAsync(Runnable::run).join();assertEquals(1,translationCalls.get());clock.advance(Duration.ofDays(1));service.todayAsync(Runnable::run).join();assertEquals(2,zenCalls.get());assertEquals(2,translationCalls.get());}
    @Test void slowTranslationFallsBackAndConcurrentCallsShareFlow()throws Exception{AtomicInteger zenCalls=new AtomicInteger(),translationCalls=new AtomicInteger();CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);QuoteTranslator slow=text->{translationCalls.incrementAndGet();entered.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}return "Slow translation";};QuoteService service=new QuoteService(zenClient(zenCalls),slow,new ZenQuotesCache(temp),CLOCK,Duration.ofMillis(75));ExecutorService pool=Executors.newFixedThreadPool(3);try{CompletableFuture<Optional<DailyQuote>> first=service.todayAsync(pool);assertTrue(entered.await(2,TimeUnit.SECONDS));CompletableFuture<Optional<DailyQuote>> second=service.todayAsync(pool);assertSame(first,second);DailyQuote quote=first.get(2,TimeUnit.SECONDS).orElseThrow();assertEquals(DailyQuote.TranslationStatus.ORIGINAL_ONLY,quote.translationStatus());assertEquals(1,zenCalls.get());assertEquals(1,translationCalls.get());}finally{release.countDown();pool.shutdownNow();}}
    @Test void cachePersistsQuotaMarker()throws Exception{ZenQuotesCache cache=new ZenQuotesCache(temp);DailyQuote q=new DailyQuote("Quote","Author",LocalDate.of(2026,10,29),DailyQuote.Origin.FRESH);cache.write(q,q.date());cache.markQuotaExhausted(q.date());assertTrue(cache.quotaExhausted(q.date()));assertEquals(q.date(),cache.read().orElseThrow().quotaExhaustedDate());}

    private static MyMemoryClient client(int status,String body){return new MyMemoryClient((m,u,h,b)->new HttpTransport.Response(status,body));}
    private static ZenQuotesClient zenClient(AtomicInteger calls){return new ZenQuotesClient((m,u,h,b)->{calls.incrementAndGet();return new HttpTransport.Response(200,"[{\"q\":\"A public quote\",\"a\":\"Author\",\"date\":\"2026-10-29\"}]");},CLOCK);}
    private static final class MutableClock extends Clock{private Instant now;private final ZoneId zone;MutableClock(Instant now,ZoneId zone){this.now=now;this.zone=zone;}void advance(Duration duration){now=now.plus(duration);}@Override public ZoneId getZone(){return zone;}@Override public Clock withZone(ZoneId zone){return zone.equals(this.zone)?this:new MutableClock(now,zone);}@Override public Instant instant(){return now;}}
}
